#!/bin/zsh
# 让 Codex 出「刘海屏快捷面板」的设计稿：从 MacBook 刘海展开的黑色面板，一键录音 + 一键导入剪贴板里的视频链接。
cd "$(dirname "$0")"
name=ui_notch
[ -f "$name.png" ] && exit 0
P="当前目录有 ref_link_current.jpg（豆仓 macOS 应用现在的界面，配色：玫瑰红强调色 #F43F5E、暖灰、绿色只表示已连接）和 ref_mascot2.png（吉祥物小豆：珍珠白圆滚滚小仓鼠，戴白色耳机）。请先看这两张图，然后使用内置的 image_gen 工具（把它们一起传入）生成一张 16:10 横向的高保真设计稿：画面是 MacBook Pro 屏幕顶部的特写（正视图、不要透视），桌面壁纸是柔和的暖色，屏幕正上方是黑色的刘海。从刘海往下展开一块和刘海融为一体的纯黑圆角面板（像苹果灵动岛那样，下沿圆角 22，宽约屏幕的 38%），里面用白色和浅灰文字：左上角一个很小的小豆头像和「soundcore Work · 已连接 · 电量 86%」（绿色小圆点）；正中一个大的玫瑰红圆形录音按钮，下面一行小字「开始录音  ⌘R」，旁边一个次要的胶囊按钮「用这台 Mac 录」；面板下半部分是一张深灰圆角小卡片：左边一个玫瑰红小方块播放图标，文字「剪贴板里有一条小红书链接」和灰色小字「为什么要搞死黄仁勋？ · @圆圆子」，右边一个玫瑰红小按钮「导入」；卡片下面一行很细的进度条和小字「正在下载 抖音 · 这波手机库存有救了 43%」。另外在画面右下角放一个小的插图（带细边框和标签「录音中」），展示收起状态：刘海两侧各伸出一点黑色的耳朵，左耳一个红色小圆点和「12:48」计时，右耳一小段跳动的红色声波。整体克制、高级，像苹果设计奖级别的 macOS 小工具。界面文字全部是简体中文，像苹方，清晰可读、没有乱码。绝对不要蓝色、紫色、琥珀橙。生成后把最终图片复制到当前目录，命名为 $name.png，然后只回复文件名。"
t0=$(date +%s)
codex exec --skip-git-repo-check --ephemeral -c 'model_reasoning_effort="low"' -C "$PWD" -s workspace-write "$P" < /dev/null > "$name.log" 2>&1
echo "$name $(( $(date +%s) - t0 ))s $([ -f $name.png ] && echo ok || echo FAIL)"
